    fun normalizeText(text: String): String {
        return text.trim()
            .replace("[\u064B-\u065F\u0670]".toRegex(), "") // Remove diacritics
            .replace("ـ", "") // Remove tatweel
            .replace("[أإآٱ]".toRegex(), "ا")
            .replace("ة", "ه")
            .replace("[ىئ]".toRegex(), "ي")
            .replace("ؤ", "و")
            .lowercase(Locale.ROOT)
    }

    fun searchCities(query: String): List<CityInfo> {
        val q = normalizeText(query)
        if (q.isEmpty()) return majorCities
        return majorCities.filter { city ->
            val nameAr = normalizeText(city.cityNameAr)
            val countryAr = normalizeText(city.countryNameAr)
            val nameEn = city.cityNameEn.lowercase(Locale.ROOT)
            val countryEn = city.countryNameEn.lowercase(Locale.ROOT)
            nameAr.contains(q) ||
            countryAr.contains(q) ||
            nameEn.contains(q) ||
            countryEn.contains(q)
        }
    }
}
